:root {
  color-scheme: light;
  font-family: system-ui, sans-serif;
  color: #19232d;
  background: #f4f7f8;
}

* { box-sizing: border-box; }

body { margin: 0; }

.shell {
  width: min(100% - 2rem, 48rem);
  margin: 4rem auto;
  padding: 2rem;
  border: 1px solid #d9e0e4;
  border-radius: 0.75rem;
  background: white;
  box-shadow: 0 0.5rem 2rem #1c344010;
}

h1 { margin-top: 0; font-size: 2rem; }

label { display: block; margin-bottom: 0.5rem; font-weight: 600; }

.form-row, .project-row { display: flex; align-items: center; gap: 0.75rem; }

.form-row input { flex: 1; min-width: 0; }

input, button {
  min-height: 2.7rem;
  padding: 0.55rem 0.8rem;
  border: 1px solid #aab8c1;
  border-radius: 0.35rem;
  font: inherit;
}

button { color: white; border-color: #176b78; background: #176b78; cursor: pointer; }
button:hover { background: #105562; }
button:focus-visible, input:focus-visible { outline: 3px solid #73c6d2; outline-offset: 2px; }

.project-list { margin-top: 1.5rem; }
.project-row { justify-content: space-between; padding: 0.8rem 0; border-top: 1px solid #e2e8eb; }
.task-list { margin-top: 1rem; }
.task-row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 0.8rem 0; border-top: 1px solid #e2e8eb; }
.task-completion { margin: 0; }
.task-completion input { min-height: auto; }
#task-filter { min-height: 2.7rem; padding: 0.4rem 0.7rem; border: 1px solid #aab8c1; border-radius: 0.35rem; font: inherit; }
.error { color: #a21d25; }

@media (max-width: 32rem) {
  .shell { margin: 1rem auto; padding: 1.25rem; }
  .form-row { align-items: stretch; flex-direction: column; }
}

